// `pnpm codegen:report` ("生成率度量"; see docs/design-notes.md#codegen): which server modules are generated (their entity starts
// with the `@generated by qw-codegen` header) and which are hand-written, and for each generated one the
// lines changed since its `scaffold via codegen` commit in the module's files. Writes
// docs/codegen-report.md. For reference only: no threshold, never fails a build (exit 0 even when git
// can't answer), not part of ci:local. An optional argument is the repository root (for
// apps/server/test/scripts/codegen-report.spec.ts).
import { execFileSync } from 'node:child_process'
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = process.argv[2]
  ? resolve(process.argv[2])
  : fileURLToPath(new URL('..', import.meta.url))
const git = (...args) => {
  try {
    return execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim()
  } catch {
    return ''
  }
}
const HEADER = /^\/\/ @generated by qw-codegen \((\w+)\)/
const cgSeeds = join(root, 'apps/server/src/db/seeds/codegen')

// a module = a directory below apps/server/src/modules holding entities
const entities = readdirSync(join(root, 'apps/server/src/modules'), { recursive: true })
  .map((p) => p.split('\\').join('/'))
  .filter((p) => p.endsWith('.entity.ts'))
  .sort()
const modules = new Map()
for (const p of entities) {
  const dir = `apps/server/src/modules/${dirname(p)}`
  const text = readFileSync(join(root, 'apps/server/src/modules', p), 'utf8')
  const m = modules.get(dir) ?? {
    dir,
    entity: `apps/server/src/modules/${p}`,
    template: null,
    tables: [],
  }
  m.template ??= HEADER.exec(text)?.[1] ?? null
  m.tables.push(/@Entity\('(\w+)'\)/.exec(text)?.[1])
  modules.set(dir, m)
}

/** The files of a generated module, by the naming of docs/codegen-golden.md. */
function filesOf(dir) {
  // home: `<domain>/<biz>` (a project domain) or `<group>/<domain>/<biz>`
  const home = dir.replace('apps/server/src/modules/', '')
  const [domain, biz] = home.split('/').slice(-2)
  return [
    `${dir}/`,
    `apps/web/src/views/${home}/`,
    `apps/server/test/e2e/${domain}-${biz}.e2e-spec.ts`,
    `packages/shared/src/${home}.schema.ts`,
    `apps/web/src/api/${home}.ts`,
    `apps/web/src/locales/*/${domain}.${biz}.json`,
    `packages/shared/src/i18n/*/modules/${domain}.${biz}.json`,
  ]
}

const rows = []
for (const m of [...modules.values()].sort((a, b) => a.dir.localeCompare(b.dir))) {
  const name = m.dir.replace('apps/server/src/modules/', '')
  if (!m.template) {
    rows.push(`| ${name} | hand-written | | | |`)
    continue
  }
  const g0 = m.tables.some((t) => existsSync(join(cgSeeds, `${t}.cg.ts`)))
  // the newest commit whose SUBJECT says `scaffold via codegen` (a body quoting it doesn't count) in the
  // entity's history, renames followed; the entity's path there gives the module's files at that time.
  // `--follow` also follows copies (another module's generated entity passes for one), so the walk
  // ends at the commit that added or copied the file.
  let scaffold, oldEntity
  const log = git(
    'log',
    '--follow',
    '--abbrev=7',
    '--format=%x01%h %s',
    '--name-status',
    '--',
    m.entity,
  )
  for (const c of log.split('\x01').slice(1)) {
    const [head, change = ''] = c.split('\n').filter(Boolean)
    if (head.includes('scaffold via codegen')) {
      scaffold = head.split(' ')[0]
      oldEntity = change.split('\t').at(-1)
      break
    }
    if (/^[AC]/.test(change)) break
  }
  const paths = new Set([...filesOf(m.dir), ...filesOf(dirname(oldEntity || m.entity))])
  const stat = scaffold ? git('diff', '-M', '--shortstat', scaffold, 'HEAD', '--', ...paths) : ''
  const n = (re) => Number(re.exec(stat)?.[1] ?? 0)
  const changed = scaffold ? `+${n(/(\d+) insertion/)} −${n(/(\d+) deletion/)}` : ''
  rows.push(
    `| ${name} | ${g0 ? 'G0' : 'G'} (${m.template}) | ${m.tables.sort().join(', ')} | ${scaffold ?? '—'} | ${changed} |`,
  )
}
const generated = [...modules.values()].filter((m) => m.template).length

writeFileSync(
  join(root, 'docs/codegen-report.md'),
  `# Codegen report

Generated by \`pnpm codegen:report\` (\`scripts/codegen-report.mjs\`) at ${git('rev-parse', '--short=7', 'HEAD') || 'an unknown commit'}. For reference only: no threshold.

- server modules: ${modules.size}, generated: ${generated} (the entity carries the \`@generated\` header), hand-written: ${modules.size - generated}
- G0: re-rendered by \`pnpm gen:check-golden\` from \`db/seeds/codegen/<table>.cg.ts\`, never edited by hand (changes since the scaffold come from template changes); G: generated, then edited by hand
- scaffold commit: the newest commit whose subject says \`scaffold via codegen\` in the history of the module's entity, renames followed (\`git log --follow\`)
- lines changed: \`git diff -M --shortstat <scaffold> HEAD\` over the module's files (server module, views, spec, schema, api, locale fragments) at their current and scaffold-time paths; no scaffold commit (a golden sample written by hand first) → none

| Module | Kind | Tables | Scaffold commit | Changed since |
| ------ | ---- | ------ | --------------- | ------------- |
${rows.join('\n')}
`,
)
console.log(
  `codegen:report: ${generated} of ${modules.size} modules generated → docs/codegen-report.md`,
)
